class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        # Initialize a dictionary to count occurrences of each character
        char_count = {}
        for char in s:
            char_count[char] = char_count.get(char, 0) + 1

        # Check if any character appears more than k times
        if any(count > k for count in char_count.values()):
            return False

        # Use a set to keep track of the unique characters in each substring
        unique_chars = set()

        # Iterate through the string to find valid substrings
        i = 0
        while i < len(s):
            current_substring = ""
            while i < len(s) and len(unique_chars) < k:
                current_substring += s[i]
                unique_chars.add(s[i])
                i += 1

            # If we have found k distinct characters, check if there's any overlap with previous substrings
            if len(unique_chars) == k:
                for j in range(len(current_substring)):
                    if current_substring[j] in unique_chars:
                        return False

            # Reset the set of unique characters for the next iteration
            unique_chars.clear()

        return True

